def _quoted(values):
    return "(" + ",".join("'" + value + "'" for value in values) + ")"


def _module(name: str):
    """An earlier migration's module, read from its own file (its own text and builders)."""
    spec = importlib.util.spec_from_file_location(f"_asl_{name[:4]}", Path(__file__).with_name(f"{name}.py"))
    earlier = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(earlier)
    return earlier


def agent_rows():
    """The frozen generation-18 documents, each checked against its own hash."""
    rows = []
    for line in AGENT_SEED_LINES_V18.strip().splitlines():
        identity, kind, version, status, canonical, sha256 = json.loads(line)
        if hashlib.sha256(canonical.encode()).hexdigest() != sha256 or kind not in AGENT_KINDS:
            raise RuntimeError("frozen generation-18 agent definition is inconsistent")
        rows.append({"id": identity, "kind": kind, "version": version, "status": status,
                     "canonical": canonical, "sha256": sha256})
    return rows


def steps_sql(kinds: tuple[str, ...], states: tuple[str, ...], length: int) -> str:
    """The steps table's kind column and its two checks of the kinds (0032 named the first by default)."""
    return (f"ALTER TABLE backtest_steps DROP CONSTRAINT backtest_steps_kind_check, DROP CONSTRAINT "
            f"backtest_step_state, ALTER COLUMN kind TYPE varchar({length}), ADD CONSTRAINT backtest_steps_kind_check "
            f"CHECK (kind IN {_quoted(kinds)}), ADD CONSTRAINT backtest_step_state CHECK ((state_sha256 IS NOT NULL) = "
            f"(kind IN {_quoted(states)}))")


# 0032's step guard with the latest run's feedback steps in the one sequence each run's steps follow; only that run has
# them, and it has no veto, shadow or probe.
STEP_GUARD_SQL = """
CREATE OR REPLACE FUNCTION asl_backtest_step_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = {path} AS $$
DECLARE last record;
BEGIN
    IF asl_is_superuser() THEN RETURN NEW; END IF;
    IF current_user <> 'asl_agent' THEN RAISE EXCEPTION 'a backtest step is the agent worker''s'; END IF;
    PERFORM 1 FROM backtest_runs WHERE id = NEW.run_id AND state = 'RUNNING' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'a backtest step needs its run running'; END IF;
    NEW.created_at := clock_timestamp();
    IF NEW.kind IN {added} AND NEW.run_id <> '{latest_run}' THEN
        RAISE EXCEPTION 'a feedback step belongs to the latest design''s run'; END IF;
    IF NEW.run_id = '{latest_run}' AND NEW.kind NOT IN {latest_kinds} THEN
        RAISE EXCEPTION 'the latest design''s run has trader and feedback steps only'; END IF;
    IF NEW.kind IN {sequence} THEN
        SELECT s.seq, EXISTS (SELECT 1 FROM backtest_answers a WHERE a.step_id = s.id) AS answered INTO last
            FROM backtest_steps s WHERE s.run_id = NEW.run_id AND s.kind IN {sequence}
            ORDER BY s.seq DESC LIMIT 1;
        IF NOT FOUND THEN
            IF NEW.seq <> 0 THEN RAISE EXCEPTION 'the first backtest step is step 0'; END IF;
        ELSIF NEW.seq <> last.seq + 1 OR NOT last.answered THEN
            RAISE EXCEPTION 'a backtest step follows the last one once it has its answer'; END IF;
    ELSIF NEW.kind = 'REAL_DATES' THEN
        IF NOT EXISTS (SELECT 1 FROM backtest_steps WHERE run_id = NEW.run_id AND kind = 'TRADER'
                AND seq = NEW.seq) THEN
            RAISE EXCEPTION 'a real-dates shadow pairs a trader step'; END IF;
    END IF;
    RETURN NEW;
END $$;
"""

# 0036's answer guard and artifact guard with the latest run's own templates of each kind, and its starts counted as
# the Claude run's (a provider failure is not one).
GUARDS_SQL = """
CREATE OR REPLACE FUNCTION asl_backtest_answer_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = {path} AS $$
DECLARE s record; w record; templates text[]; paid boolean;
BEGIN
    IF asl_is_superuser() THEN RETURN NEW; END IF;
    IF current_user <> 'asl_agent' THEN RAISE EXCEPTION 'a backtest answer is the agent worker''s'; END IF;
    NEW.recorded_at := clock_timestamp();
    SELECT st.run_id, st.kind INTO s FROM backtest_steps st WHERE st.id = NEW.step_id;
    IF NOT FOUND OR s.run_id <> NEW.run_id THEN RAISE EXCEPTION 'a backtest answer answers a step of its run'; END IF;
    PERFORM 1 FROM backtest_runs WHERE id = NEW.run_id AND state = 'RUNNING';
    IF NOT FOUND THEN RAISE EXCEPTION 'a backtest answer needs its run running'; END IF;
    paid := NEW.run_id IN ('{claude_run}', '{latest_run}');
    templates := CASE WHEN NEW.run_id = '{latest_run}' THEN CASE s.kind {latest_cases} END
        WHEN NEW.run_id = '{claude_run}' THEN CASE s.kind {claude_cases} END ELSE CASE s.kind {cases} END END;
    IF NEW.outcome = 'UNANSWERED' THEN
        IF EXISTS (SELECT 1 FROM agent_workflows WHERE template_id = ANY(templates)
                AND params->'backtest'->>'step_id' = NEW.step_id::text
                AND state IN ('QUEUED','RUNNING','WAITING_TOOL','WAITING_REVIEW'))
                OR (SELECT count(*) FROM agent_workflows aw WHERE aw.template_id = ANY(templates)
                    AND aw.params->'backtest'->>'step_id' = NEW.step_id::text
                    AND (aw.started_at IS NOT NULL OR aw.state = 'FAILED')
                    AND NOT (aw.state = 'CANCELED' AND COALESCE(aw.terminal_reason, '') = 'YIELDED_TO_DECISION')
                    AND NOT (paid AND {failure}))
                    < {starts} THEN
            RAISE EXCEPTION 'a backtest step is given up only after its starts, with none open'; END IF;
        RETURN NEW;
    END IF;
    SELECT template_id, purpose, state, parent_id, created_by, params INTO w FROM agent_workflows
        WHERE id = NEW.workflow_id;
    IF NOT FOUND OR w.purpose <> 'BACKTEST' OR w.parent_id IS NOT NULL OR w.created_by <> 'SYSTEM'
            OR NOT COALESCE(w.template_id = ANY(templates), false)
            OR w.params->'backtest'->>'step_id' IS DISTINCT FROM NEW.step_id::text
            OR w.params->'backtest'->>'run' IS DISTINCT FROM NEW.run_id THEN
        RAISE EXCEPTION 'a backtest answer comes from the workflow started for its step'; END IF;
    IF NEW.outcome = 'ABSTAINED' THEN
        IF w.state <> 'ABSTAINED' THEN RAISE EXCEPTION 'an abstention names the workflow that abstained'; END IF;
        RETURN NEW;
    END IF;
    IF w.state <> 'RUNNING' THEN RAISE EXCEPTION 'a backtest answer comes from its running workflow'; END IF;
    IF NOT EXISTS (SELECT 1 FROM agent_artifacts WHERE workflow_id = NEW.workflow_id AND kind = 'BACKTEST_ANSWER'
            AND sha256 = NEW.artifact_sha256 AND document -> 'answer' = NEW.answer) THEN
        RAISE EXCEPTION 'a backtest answer is its workflow''s recorded artifact'; END IF;
    RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION asl_backtest_artifact_guard() RETURNS trigger LANGUAGE plpgsql SET search_path = {path} AS $$
DECLARE w record; d jsonb := NEW.document;
BEGIN
    IF asl_is_superuser() THEN RETURN NEW; END IF;
    IF current_user <> 'asl_agent' THEN RAISE EXCEPTION 'a backtest answer comes only from its agent'; END IF;
    SELECT template_id, purpose, state, parent_id, params INTO w FROM agent_workflows WHERE id = NEW.workflow_id;
    IF NOT FOUND OR w.state <> 'RUNNING' OR w.parent_id IS NOT NULL OR w.purpose <> 'BACKTEST'
            OR w.template_id NOT IN {templates} THEN
        RAISE EXCEPTION 'a backtest answer needs its own running backtest workflow'; END IF;
    -- In parentheses: an IF's condition is read up to its first THEN outside them.
    IF w.params->'backtest'->>'run' IS DISTINCT FROM (CASE WHEN w.template_id IN {latest_templates}
            THEN '{latest_run}' WHEN w.template_id IN {claude_templates} THEN '{claude_run}'
            ELSE '{chatgpt_run}' END) THEN
        RAISE EXCEPTION 'a backtest workflow answers its own template''s run'; END IF;
    IF d->>'step_id' IS DISTINCT FROM w.params->'backtest'->>'step_id'
            OR d->>'run' IS DISTINCT FROM w.params->'backtest'->>'run' THEN
        RAISE EXCEPTION 'a backtest answer names the step its workflow was started for'; END IF;
    RETURN NEW;
END $$;
"""


def step_guard_sql() -> str:
    return (STEP_GUARD_SQL.replace("{path}", SEARCH_PATH)
            .replace("{sequence}", _quoted((*SEQUENCE_0032, *KINDS_ADDED))).replace("{added}", _quoted(KINDS_ADDED))
            .replace("{latest_kinds}", _quoted(tuple(kind for kind, _template in LATEST_KINDS)))
            .replace("{latest_run}", RUN_LATEST))


def guards_sql() -> str:
    earlier = _module("0036_claude_backtest")
    cases = " ".join(f"WHEN '{kind}' THEN ARRAY{list(chatgpt)}" for kind, chatgpt, _claude in earlier.KINDS)
    claude_cases = " ".join(f"WHEN '{kind}' THEN ARRAY['{claude}']" for kind, _chatgpt, claude in earlier.KINDS)
    latest_cases = " ".join(f"WHEN '{kind}' THEN ARRAY['{template}']" for kind, template in LATEST_KINDS)
    return (GUARDS_SQL.replace("{path}", SEARCH_PATH).replace("{latest_cases}", latest_cases)
            .replace("{claude_cases}", claude_cases).replace("{cases}", cases)
            .replace("{failure}", earlier.failure_sql("aw"))
            .replace("{latest_templates}", _quoted(TEMPLATES)).replace("{claude_templates}", _quoted(earlier.TEMPLATES))
            .replace("{templates}", _quoted((*earlier.TEMPLATES_CHATGPT, *earlier.TEMPLATES, *TEMPLATES)))
            .replace("{latest_run}", RUN_LATEST).replace("{claude_run}", RUN_CLAUDE)
            .replace("{chatgpt_run}", RUN_CHATGPT).replace("{starts}", str(STARTS_PER_STEP)))


def step_guard_0032_sql() -> str:
    """0032's step guard exactly as 0032 created it (its own text), as a replacement."""
    earlier = _module("0032_ai_backtest")
    text = earlier.GUARDS_SQL
    start, end = text.index("-- A step:"), text.index("-- An answer:")
    return text[start:end].replace("CREATE FUNCTION", "CREATE OR REPLACE FUNCTION").replace("{path}", earlier.SEARCH_PATH)


def upgrade() -> None:
    op.execute("SET LOCAL lock_timeout = '10s'")
    bind = op.get_bind()
    earlier = _module("0036_claude_backtest")
    op.execute(earlier.checks_sql((RUN_CHATGPT, RUN_CLAUDE, RUN_LATEST), earlier.CODES))
    op.execute(steps_sql((*KINDS_0032, *KINDS_ADDED), (*STATE_0032, *KINDS_ADDED), 16))
    op.execute(step_guard_sql())
    op.execute(guards_sql())
    for row in agent_rows():
        bind.exec_driver_sql(
            "INSERT INTO agent_definitions (id, kind, version, status, definition, canonical, sha256) "
            "VALUES (%(id)s, %(kind)s, %(version)s, %(status)s, CAST(%(definition)s AS jsonb), %(canonical)s, "
            "%(sha256)s)", {**row, "definition": row["canonical"]})  # one name per use: each has its own type


def downgrade() -> None:
    op.execute("SET LOCAL lock_timeout = '10s'")
    bind = op.get_bind()
    # Nothing new can be stored between the count and the change.
    op.execute("LOCK TABLE backtest_runs, backtest_steps, backtest_answers IN ACCESS EXCLUSIVE MODE")
    # A runtime profile that binds generation 18 by hash would bind definitions that no longer exist (as 0036's); the
    # third run, its steps and its workflows need these guards and checks.
    generation18 = [row["id"] for row in agent_rows()]
    held = bind.exec_driver_sql(
        f"SELECT (SELECT count(*) FROM agent_workflows WHERE template_id IN {_quoted(TEMPLATES)}) "
        f"+ (SELECT count(*) FROM backtest_runs WHERE id = '{RUN_LATEST}') "
        f"+ (SELECT count(*) FROM backtest_steps WHERE kind IN {_quoted(KINDS_ADDED)}) "
        f"+ (SELECT count(*) FROM agent_runtime_profiles WHERE profile -> 'definitions' ?| ARRAY{generation18})"
    ).scalar_one()
    if held:
        raise RuntimeError("generation-18 records exist; downgrade refused; fix forward")
    op.execute("ALTER TABLE agent_definitions DISABLE TRIGGER agent_definitions_immutable")
    for row in agent_rows():
        if bind.exec_driver_sql("DELETE FROM agent_definitions WHERE id = %(id)s AND sha256 = %(sha256)s",
                                row).rowcount != 1:
            raise RuntimeError("generation-18 definition mismatch; downgrade refused")
    op.execute("ALTER TABLE agent_definitions ENABLE TRIGGER agent_definitions_immutable")
    earlier = _module("0036_claude_backtest")
    op.execute(earlier.guards_sql())
    op.execute(step_guard_0032_sql())
    op.execute(steps_sql(KINDS_0032, STATE_0032, 10))
    op.execute(earlier.checks_sql((RUN_CHATGPT, RUN_CLAUDE), earlier.CODES))
